import{_ as a,o as t,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Alipay 明細インポート","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/03-alipay-bill-import-guide.md","filePath":"v1/ja/guide/03-alipay-bill-import-guide.md"}'),o={name:"v1/ja/guide/03-alipay-bill-import-guide.md"};function e(d,l,n,h,s,c){return t(),i("div",null,[...l[0]||(l[0]=[r('<h1 id="alipay-明細インポート" tabindex="-1">Alipay 明細インポート <a class="header-anchor" href="#alipay-明細インポート" aria-label="Permalink to &quot;Alipay 明細インポート&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>本ガイドでは、Alipay から明細をエクスポートし、コアラ家計簿にインポートする手順を説明します。</p><hr><h2 id="📱-手順-1-alipay-で明細をエクスポート" tabindex="-1">📱 手順 1：Alipay で明細をエクスポート <a class="header-anchor" href="#📱-手順-1-alipay-で明細をエクスポート" aria-label="Permalink to &quot;📱 手順 1：Alipay で明細をエクスポート&quot;">​</a></h2><h3 id="手順-1-明細-账单-画面を開く" tabindex="-1">手順 1：明細（账单）画面を開く <a class="header-anchor" href="#手順-1-明細-账单-画面を開く" aria-label="Permalink to &quot;手順 1：明細（账单）画面を開く&quot;">​</a></h3><ol><li>Alipay を開く</li><li>画面下の <strong>「我的」</strong> をタップ</li><li><strong>「账单」</strong> をタップして明細画面へ</li></ol><blockquote><p>📝 注意：Alipay のバージョンにより入口が異なる場合があります。見つからない場合は、Alipay の検索で「账单」を検索してみてください。</p></blockquote><h3 id="手順-2-エクスポートを開始" tabindex="-1">手順 2：エクスポートを開始 <a class="header-anchor" href="#手順-2-エクスポートを開始" aria-label="Permalink to &quot;手順 2：エクスポートを開始&quot;">​</a></h3><ol><li>明細画面で右上の <strong>「...」</strong> をタップ</li><li><strong>「开具交易流水证明」</strong> または <strong>「账单导出」</strong>（表記はバージョンにより異なる）を選択</li><li><strong>「用户个人对帐」</strong> を選び、<strong>「申请」</strong> をタップ</li></ol><h3 id="手順-3-範囲と受け取り方法を選択" tabindex="-1">手順 3：範囲と受け取り方法を選択 <a class="header-anchor" href="#手順-3-範囲と受け取り方法を選択" aria-label="Permalink to &quot;手順 3：範囲と受け取り方法を選択&quot;">​</a></h3><ol><li>取引種別：<strong>全部交易</strong> / <strong>收入</strong> / <strong>支出</strong></li><li>期間（例：直近 1 か月 / 直近 3 か月など）</li><li>受け取り方法：<strong>支付宝</strong> / <strong>邮箱</strong></li></ol><blockquote><p>💡 ヒント：</p><ul><li>1 回のエクスポートは 3 か月以内をおすすめします（ファイルが大きいと処理が遅くなることがあります）。</li><li>長期間の履歴は複数回に分けてエクスポートしてください。</li><li>メール受け取りの場合は、Alipay 側でメールアドレス設定が必要です。</li></ul></blockquote><h3 id="手順-4-端末に保存" tabindex="-1">手順 4：端末に保存 <a class="header-anchor" href="#手順-4-端末に保存" aria-label="Permalink to &quot;手順 4：端末に保存&quot;">​</a></h3><ol><li>メール受け取りの場合： <ul><li>メールアプリで Alipay からのメールを開く</li><li>添付ファイル（CSV）をダウンロード</li><li>端末内（ファイルアプリで参照できる場所）に保存</li></ul></li><li>「ファイルに保存」できる場合： <ul><li>ダウンロードフォルダ等に保存</li><li>保存先を覚えておく</li></ul></li></ol><blockquote><p>📝 保存先の目安：</p><ul><li>iOS：ファイル App → ダウンロード</li><li>Android：ダウンロードフォルダ、または Alipay フォルダ</li></ul></blockquote><hr><h2 id="📱-手順-2-コアラ家計簿にインポート" tabindex="-1">📱 手順 2：コアラ家計簿にインポート <a class="header-anchor" href="#📱-手順-2-コアラ家計簿にインポート" aria-label="Permalink to &quot;📱 手順 2：コアラ家計簿にインポート&quot;">​</a></h2><h3 id="手順-1-インポート画面を開く" tabindex="-1">手順 1：インポート画面を開く <a class="header-anchor" href="#手順-1-インポート画面を開く" aria-label="Permalink to &quot;手順 1：インポート画面を開く&quot;">​</a></h3><ol><li>コアラ家計簿を開く</li><li>画面下の <strong>「設定」</strong> をタップ</li><li><strong>「明細インポート」</strong> を探して開く</li></ol><h3 id="手順-2-インポート元を選択" tabindex="-1">手順 2：インポート元を選択 <a class="header-anchor" href="#手順-2-インポート元を選択" aria-label="Permalink to &quot;手順 2：インポート元を選択&quot;">​</a></h3><ol><li><strong>「インポート元」</strong> をタップ</li><li><strong>「Alipay」</strong> を選択</li></ol><blockquote><p>⚠️ 重要：必ず Alipay を選択してください。選択を間違えるとファイル形式を正しく解析できません。</p></blockquote><h3 id="手順-3-ファイルを選択" tabindex="-1">手順 3：ファイルを選択 <a class="header-anchor" href="#手順-3-ファイルを選択" aria-label="Permalink to &quot;手順 3：ファイルを選択&quot;">​</a></h3><ol><li><strong>「ファイルパス」</strong> をタップ</li><li>Alipay からエクスポートした <strong>CSV</strong>（<code>.csv</code>）を選択</li><li>ファイル名が表示されることを確認</li></ol><h3 id="手順-4-帳本-ledger-を関連付け" tabindex="-1">手順 4：帳本（Ledger）を関連付け <a class="header-anchor" href="#手順-4-帳本-ledger-を関連付け" aria-label="Permalink to &quot;手順 4：帳本（Ledger）を関連付け&quot;">​</a></h3><ol><li><strong>「関連付け帳本」</strong> をタップ</li><li>取り込み先の帳本を選択</li></ol><h3 id="手順-5-解析-→-プレビュー-→-インポート" tabindex="-1">手順 5：解析 → プレビュー → インポート <a class="header-anchor" href="#手順-5-解析-→-プレビュー-→-インポート" aria-label="Permalink to &quot;手順 5：解析 → プレビュー → インポート&quot;">​</a></h3><ol><li>右上の <strong>「解析」</strong> をタップ</li><li>プレビュー画面で内容を確認し、必要に応じてカテゴリ/口座/メモ等を調整</li><li><strong>「インポート」</strong> をタップ</li></ol><hr><h2 id="📋-alipay-csv-の列-参考" tabindex="-1">📋 Alipay CSV の列（参考） <a class="header-anchor" href="#📋-alipay-csv-の列-参考" aria-label="Permalink to &quot;📋 Alipay CSV の列（参考）&quot;">​</a></h2><p>Alipay の CSV は通常、次の列を含みます。</p><table tabindex="0"><thead><tr><th>列名（エクスポートの表記）</th><th>内容</th><th>例</th></tr></thead><tbody><tr><td>交易时间</td><td>取引日時</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易分类</td><td>分類</td><td>餐饮美食/日用百货</td></tr><tr><td>交易对方</td><td>相手先</td><td>张三 / 商户名称</td></tr><tr><td>对方账号</td><td>相手アカウント</td><td><a href="mailto:xxx@163.com" target="_blank" rel="noreferrer">xxx@163.com</a></td></tr><tr><td>商品说明</td><td>内容</td><td>午餐 / 购物等</td></tr><tr><td>收/支</td><td>収入/支出</td><td>收入 / 支出</td></tr><tr><td>金额</td><td>金額</td><td>100.00</td></tr><tr><td>收/付款方式</td><td>支払方法/口座</td><td>余额宝</td></tr><tr><td>交易状态</td><td>状態</td><td>交易成功 / 已退款</td></tr><tr><td>交易订单号</td><td>取引注文番号</td><td>20240101...</td></tr><tr><td>商家订单号</td><td>店舗注文番号</td><td>1234567890</td></tr><tr><td>备注</td><td>メモ</td><td>备注内容</td></tr></tbody></table><blockquote><p>📝 注意：列名はバージョンによって多少異なる場合がありますが、内容はほぼ同じです。</p></blockquote><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><h3 id="_1-ファイルの条件" tabindex="-1">1. ファイルの条件 <a class="header-anchor" href="#_1-ファイルの条件" aria-label="Permalink to &quot;1. ファイルの条件&quot;">​</a></h3><ul><li><strong>文字コード</strong>：UTF-8 推奨（Alipay は UTF-8 または GBK の場合があります）</li><li><strong>形式</strong>：CSV のみ（<code>.csv</code>）</li><li><strong>サイズ</strong>：1 ファイル 10MB 以下を推奨</li></ul><h3 id="_2-取り込みの扱い-概要" tabindex="-1">2. 取り込みの扱い（概要） <a class="header-anchor" href="#_2-取り込みの扱い-概要" aria-label="Permalink to &quot;2. 取り込みの扱い（概要）&quot;">​</a></h3><p>コアラ家計簿は Alipay の列を自動でコアラ家計簿の項目に変換します。</p><ul><li>交易时间（row[0]）→ 日付（<code>yyyy-MM-dd</code> の日付のみとして取り込み）</li><li>交易分类（row[1]）→ カテゴリ（親子とも同名で取り込み）</li><li>收/支（row[5]）→ 収入/支出</li><li>金额（row[6]）→ 金額</li><li>收/付款方式（row[7]）→ 口座（名称で照合、存在しない場合は作成されることがあります）</li><li>交易对方/对方账号/商品说明/交易状态/订单号等 → メモとして結合</li><li>备注（row[11]）→ 元のメモ（「/」や空は無視され、上記の追記が加わります）</li></ul><h3 id="_3-重複・返金の扱い" tabindex="-1">3. 重複・返金の扱い <a class="header-anchor" href="#_3-重複・返金の扱い" aria-label="Permalink to &quot;3. 重複・返金の扱い&quot;">​</a></h3><ul><li>取引番号などから重複と判断された場合、スキップされることがあります。</li><li>返金は「已退款/退款成功」などで表現されることが多いため、プレビューで確認してください。</li></ul><h3 id="_4-ファイルは編集しない" tabindex="-1">4. ファイルは編集しない <a class="header-anchor" href="#_4-ファイルは編集しない" aria-label="Permalink to &quot;4. ファイルは編集しない&quot;">​</a></h3><p>Alipay から書き出した CSV は、<strong>ヘッダー名の変更・列の削除・列の追加</strong> をしないでください。解析に失敗する原因になります。</p><hr><h2 id="🔧-よくある質問" tabindex="-1">🔧 よくある質問 <a class="header-anchor" href="#🔧-よくある質問" aria-label="Permalink to &quot;🔧 よくある質問&quot;">​</a></h2><h3 id="q1-「账单导出」が見つかりません" tabindex="-1">Q1：「账单导出」が見つかりません <a class="header-anchor" href="#q1-「账单导出」が見つかりません" aria-label="Permalink to &quot;Q1：「账单导出」が見つかりません&quot;">​</a></h3><p>可能性：</p><ol><li>Alipay のバージョンが古い</li><li>入口が別の場所にある</li></ol><p>試すこと：</p><ul><li>明細画面の右上 <strong>「...」</strong> を確認</li><li>「我的」から <strong>账单</strong> を探す</li><li>検索で「账单导出」を検索</li></ul><h3 id="q2-メールが届きません" tabindex="-1">Q2：メールが届きません <a class="header-anchor" href="#q2-メールが届きません" aria-label="Permalink to &quot;Q2：メールが届きません&quot;">​</a></h3><p>確認：</p><ol><li>Alipay にメールアドレスを設定済みか</li><li>アドレスが正しいか</li><li>迷惑メールフォルダ</li><li>「ファイルに保存」方式を試す</li></ol><h3 id="q3-解析に失敗します" tabindex="-1">Q3：解析に失敗します <a class="header-anchor" href="#q3-解析に失敗します" aria-label="Permalink to &quot;Q3：解析に失敗します&quot;">​</a></h3><p>確認：</p><ol><li>CSV 形式か</li><li>インポート元が Alipay か</li><li>ファイルが破損していないか</li><li>文字コード（UTF-8 / GBK）</li></ol><h3 id="q4-カテゴリが期待通りになりません" tabindex="-1">Q4：カテゴリが期待通りになりません <a class="header-anchor" href="#q4-カテゴリが期待通りになりません" aria-label="Permalink to &quot;Q4：カテゴリが期待通りになりません&quot;">​</a></h3><p>Alipay の分類とコアラ家計簿の分類が一致しない場合があります。プレビュー画面で修正するか、インポート後にまとめて編集してください。</p><h3 id="q5-画像を取り込めますか" tabindex="-1">Q5：画像を取り込めますか？ <a class="header-anchor" href="#q5-画像を取り込めますか" aria-label="Permalink to &quot;Q5：画像を取り込めますか？&quot;">​</a></h3><p>現時点では対応していません。</p><h3 id="q6-どのくらいの期間を取り込めますか" tabindex="-1">Q6：どのくらいの期間を取り込めますか？ <a class="header-anchor" href="#q6-どのくらいの期間を取り込めますか" aria-label="Permalink to &quot;Q6：どのくらいの期間を取り込めますか？&quot;">​</a></h3><p>制限はありませんが、次を推奨します。</p><ol><li>1 回の取り込みは 3 か月程度まで</li><li>大量の場合はファイルを分割</li><li>インポート中はアプリを前面にしておく</li></ol><h3 id="q7-なぜ-csv-のみ対応ですか" tabindex="-1">Q7：なぜ CSV のみ対応ですか？ <a class="header-anchor" href="#q7-なぜ-csv-のみ対応ですか" aria-label="Permalink to &quot;Q7：なぜ CSV のみ対応ですか？&quot;">​</a></h3><p>現在 Alipay のエクスポート形式が CSV のためです。将来 Excel に対応した場合はガイドを更新します。</p><hr><h2 id="💡-使い方のコツ" tabindex="-1">💡 使い方のコツ <a class="header-anchor" href="#💡-使い方のコツ" aria-label="Permalink to &quot;💡 使い方のコツ&quot;">​</a></h2><ol><li>毎月など定期的に取り込むと管理しやすい</li><li>取り込み後にカテゴリを整理すると集計が見やすくなる</li><li>よく使う口座は先に作成しておくと、口座名が自動生成されにくい</li><li>念のため、取り込み前にバックアップを推奨</li><li>返金明細がある場合は取り込み後に確認</li></ol><hr><p><strong>最終更新</strong>：2026 年 5 月</p>',72)])])}const q=a(o,[["render",e]]);export{p as __pageData,q as default};
